class Solution { fun maxSum(nums1:IntArray,nums2:IntArray):Int{var i=0;var j=0;var first=0L;var second=0L;while(i<nums1.size&&j<nums2.size)if(nums1[i]<nums2[j])first+=nums1[i++]else if(nums1[i]>nums2[j])second+=nums2[j++]else{val common=maxOf(first,second)+nums1[i];first=common;second=common;i++;j++};while(i<nums1.size)first+=nums1[i++];while(j<nums2.size)second+=nums2[j++];return (maxOf(first,second)%1_000_000_007L).toInt()} }
